package local.tvmorph.tv;
import android.content.*;import org.json.*;import java.util.*;
final class UiSettings{
 static android.content.SharedPreferences prefs(Context c){return c.getSharedPreferences("tvmorph-ui",0);}
 static String language(Context c){return prefs(c).getString("language","en");}
 static boolean modern(Context c){return prefs(c).getString("uiMode","classic").equals("modern");}
 static int color(Context c,String key,int fallback){if(!modern(c))return fallback;try{String value=prefs(c).getString(key,"");if(value.matches("#[0-9a-fA-F]{6}"))return android.graphics.Color.parseColor(value);}catch(Exception ignored){}return fallback;}
 static float fontScale(Context c){String size=prefs(c).getString(language(c).equals("ar")?"fontSizeAr":"fontSizeEn","normal");return size.equals("small")?0.9f:size.equals("large")?1.1f:1f;}
 static String text(Context c,String ar,String en){return language(c).equals("ar")?ar:en;}
 static JSONObject get(Context c)throws Exception{return new JSONObject().put("uiMode",prefs(c).getString("uiMode","classic")).put("fontSizeAr",prefs(c).getString("fontSizeAr","normal")).put("fontSizeEn",prefs(c).getString("fontSizeEn","normal")).put("language",language(c)).put("scale",prefs(c).getString("scale","fit")).put("resume",prefs(c).getBoolean("resume",true)).put("viewerName",prefs(c).getString("viewerName","Family")).put("viewerId",prefs(c).getString("viewerId","default")).put("theme",prefs(c).getString("theme","blue")).put("cardColor",prefs(c).getString("cardColor","")).put("accent",prefs(c).getString("accent","")).put("glassOpacity",prefs(c).getInt("glassOpacity",18));}
 static JSONObject save(Context c,JSONObject value)throws Exception{android.content.SharedPreferences.Editor e=prefs(c).edit();if(value.has("uiMode")&&Arrays.asList("classic","modern").contains(value.optString("uiMode")))e.putString("uiMode",value.optString("uiMode"));String language=value.optString("language"),scale=value.optString("scale");if(Arrays.asList("ar","en","fr","zh","ja").contains(language))e.putString("language",language);if(Arrays.asList("fit","fill","stretch").contains(scale))e.putString("scale",scale);if(value.has("resume"))e.putBoolean("resume",value.getBoolean("resume"));if(value.has("theme")&&Arrays.asList("blue","night","emerald","amber","violet","ahly","zamalek","barcelona","madrid","egypt","basketball","baseball","montreal","toronto","argentina","portugal","ismaily","king-salman","crown-prince","nassr","hilal","ittihad","ahli-saudi","inter-miami","saudi-national","egypt-national","blue-cinema","gta6").contains(value.optString("theme")))e.putString("theme",value.optString("theme"));for(String key:new String[]{"cardColor","accent","uiBg","uiSurface","uiAccent","uiText"})if(value.has(key)){String hex=value.optString(key);e.putString(key,hex.matches("#[0-9a-fA-F]{6}")?hex:"");}if(value.has("glassOpacity"))e.putInt("glassOpacity",Math.max(10,Math.min(80,value.optInt("glassOpacity",18))));if(value.has("viewerId")&&value.optString("viewerId").matches("(default|v[0-9a-z]+)"))e.putString("viewerId",value.optString("viewerId"));if(value.has("viewerName")){String name=value.optString("viewerName","Family");e.putString("viewerName",name.substring(0,Math.min(24,name.length())));}for(String key:new String[]{"fontSizeAr","fontSizeEn"})if(value.has(key)&&Arrays.asList("small","normal","large").contains(value.optString(key)))e.putString(key,value.optString(key));e.apply();return get(c);}
}
